static inline uint64_t ld64(const unsigned char *p){uint64_t v; memcpy(&v,p,8); return v;}

typedef struct { uint64_t h0,h1,h2; uint64_t r0,r1,r2,s1,s2; } pstate;

static void poly_init(pstate *st, const unsigned char *key){
    uint64_t t0=ld64(key), t1=ld64(key+8);
    st->r0 = t0 & 0xffc0fffffffULL;
    st->r1 = ((t0>>44)|(t1<<20)) & 0xfffffc0ffffULL;
    st->r2 = (t1>>24) & 0x00ffffffc0fULL;
    st->s1 = st->r1*(5<<2); st->s2 = st->r2*(5<<2);
    st->h0=st->h1=st->h2=0;
