static void poly_blocks(pstate *st, const unsigned char *m, size_t nblk){
    const uint64_t hibit = 1ULL<<40;
    uint64_t r0=st->r0,r1=st->r1,r2=st->r2,s1=st->s1,s2=st->s2;
    uint64_t h0=st->h0,h1=st->h1,h2=st->h2,c;
    while(nblk--){
        uint64_t t0=ld64(m), t1=ld64(m+8);
        h0 += t0 & 0xfffffffffffULL;
        h1 += ((t0>>44)|(t1<<20)) & 0xfffffffffffULL;
        h2 += ((t1>>24) & 0x3ffffffffffULL) | hibit;
        u128 d0 = (u128)h0*r0 + (u128)h1*s2 + (u128)h2*s1;
        u128 d1 = (u128)h0*r1 + (u128)h1*r0 + (u128)h2*s2;
        u128 d2 = (u128)h0*r2 + (u128)h1*r1 + (u128)h2*r0;
        c = (uint64_t)(d0>>44); h0 = (uint64_t)d0 & 0xfffffffffffULL;
        d1 += c; c = (uint64_t)(d1>>44); h1 = (uint64_t)d1 & 0xfffffffffffULL;
        d2 += c; c = (uint64_t)(d2>>42); h2 = (uint64_t)d2 & 0x3ffffffffffULL;
        h0 += c*5; c = h0>>44; h0 &= 0xfffffffffffULL; h1 += c;
        m += 16;
    }
    st->h0=h0; st->h1=h1; st->h2=h2;
}

typedef struct {
    const unsigned char *in; unsigned char *out; size_t len; /* len multiple of 64 except last */
    uint32_t counter; const unsigned char *key, *nonce;
    unsigned char rkey[16];
    uint64_t h[3]; int err;
} job;

#define SUB 8192
static void *worker(void *arg){
