    memcpy(iv,&j->counter,4); memcpy(iv+4,j->nonce,12);
    EVP_CIPHER_CTX *ctx=EVP_CIPHER_CTX_new();
    pstate st; poly_init(&st,j->rkey);
    if(!ctx || !EVP_EncryptInit_ex(ctx,CH,NULL,j->key,iv)){ j->err=1; return NULL; }
    size_t off=0;
    while(off<j->len){
        size_t n = j->len-off; if(n>SUB) n=SUB;
        int ol;
        EVP_EncryptUpdate(ctx,j->out+off,&ol,j->in+off,(int)n);
        size_t nb=n/16;
