/* encrypt(key, nonce, pt, nthreads) -> (ct, polykey32, [(h_bytes, nblocks), ...]) */
static PyObject *encrypt(PyObject *self, PyObject *args){
    Py_buffer kb, nb, pb; int nt;
    if(!PyArg_ParseTuple(args,"y*y*y*i",&kb,&nb,&pb,&nt)) return NULL;
    if(!CH) CH = EVP_CIPHER_fetch(NULL,"ChaCha20",NULL);
    size_t L = pb.len;
    unsigned char pk[64]={0}, zero[64]={0}, iv[16]={0};
    memcpy(iv+4,nb.buf,12);
    {EVP_CIPHER_CTX *c=EVP_CIPHER_CTX_new(); int ol;
     EVP_EncryptInit_ex(c,CH,NULL,kb.buf,iv); EVP_EncryptUpdate(c,pk,&ol,zero,64); EVP_CIPHER_CTX_free(c);}
    PyObject *ct = PyBytes_FromStringAndSize(NULL, L);
    if(!ct){PyBuffer_Release(&kb);PyBuffer_Release(&nb);PyBuffer_Release(&pb);return NULL;}
    unsigned char *out=(unsigned char*)PyBytes_AS_STRING(ct);
    size_t nblk64 = (L+63)/64;
    if(nt<1) nt=1;
    if((size_t)nt>nblk64) nt = nblk64 ? (int)nblk64 : 1;
    job jobs[64]; pthread_t th[64];
    if(nt>64) nt=64;
    size_t per = nblk64/nt, rem = nblk64%nt, pos=0;
    for(int i=0;i<nt;i++){
        size_t cnt = per + ((size_t)i<rem);
        size_t st=pos*64, en=(pos+cnt)*64; if(en>L) en=L; if(st>L) st=L;
        jobs[i].in=(unsigned char*)pb.buf+st; jobs[i].out=out+st; jobs[i].len=en-st;
        jobs[i].counter=(uint32_t)(1+pos); jobs[i].key=kb.buf; jobs[i].nonce=nb.buf;
        memcpy(jobs[i].rkey,pk,16); jobs[i].err=0;
        pos+=cnt;
    }
    Py_BEGIN_ALLOW_THREADS
    for(int i=1;i<nt;i++) pthread_create(&th[i],NULL,worker,&jobs[i]);
    worker(&jobs[0]);
    for(int i=1;i<nt;i++) pthread_join(th[i],NULL);
    Py_END_ALLOW_THREADS
    PyObject *lst=PyList_New(nt);
    for(int i=0;i<nt;i++){
        /* h = h0 + h1<<44 + h2<<88 */
        PyObject *a=PyLong_FromUnsignedLongLong(jobs[i].h[0]);
        PyObject *b=PyLong_FromUnsignedLongLong(jobs[i].h[1]);
        PyObject *c=PyLong_FromUnsignedLongLong(jobs[i].h[2]);
        PyList_SET_ITEM(lst,i,Py_BuildValue("(NNNn)",a,b,c,(Py_ssize_t)((jobs[i].len+15)/16)));
    }
    PyBuffer_Release(&kb);PyBuffer_Release(&nb);PyBuffer_Release(&pb);
    return Py_BuildValue("(Ny#N)",ct,(char*)pk,(Py_ssize_t)32,lst);
}
