import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import fastcc2

P = (1 << 130) - 5
M128 = (1 << 128) - 1
NT = 12


def _poly_blocks(h, r, data):
    n = len(data)
    for i in range(0, n, 16):
        blk = data[i:i + 16]
        if len(blk) < 16:
            blk = blk + bytes(16 - len(blk))
        h = ((h + int.from_bytes(blk, "little") + (1 << 128)) * r) % P
    return h


class Solver:
    def solve(self, problem, **kwargs):
        key = problem["key"]
        nonce = problem["nonce"]
        pt = problem["plaintext"]
        aad = problem.get("associated_data") or b""
        if len(key) != 32 or len(nonce) != 12:
            raise ValueError("bad key/nonce")
        nt = NT if len(pt) >= (1 << 20) else 1
        ct, pk, segs = fastcc2.encrypt(key, nonce, pt, nt)
        r = int.from_bytes(pk[:16], "little") & 0x0ffffffc0ffffffc0ffffffc0fffffff
        s = int.from_bytes(pk[16:32], "little")
        h = _poly_blocks(0, r, aad)
        for ta, tb, nb in segs:
            a = int.from_bytes(ta, "little")
            b = int.from_bytes(tb, "little")
            hs = None
            for k in range(4):
                c = a + (k << 128)
                if c >= P:
